        uint beforeContract = address(c).balance;
        uint beforeThis = c.balances(address(this)); if (__ESBMC_reverted()) return;
        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint afterThis = c.balances(address(this)); if (__ESBMC_reverted()) return;
