contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint beforeContract = address(c).balance;
        uint256 beforeThis;
        try c.balances(address(this)) returns (uint256 __r) { beforeThis = __r; } catch { return; }
        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }
        uint256 afterThis;
        try c.balances(address(this)) returns (uint256 __r) { afterThis = __r; } catch { return; }
        uint afterContract = address(c).balance;
        assertTrue(reverted || (afterThis == beforeThis && afterThis == 0 && afterContract == beforeContract));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

